{
  "q1_human_microarray_expression_profiling": {
    "answer": "Yes",
    "evidence": "Study type: transcription profiling by array; Organism: Homo sapiens",
    "justification": "The dataset employs microarray-based transcription profiling on human samples."
  },
  "q2_target_disease": {
    "answer": "Yes",
    "evidence": "Disease: Parkinson's disease",
    "justification": "Parkinson's disease is a Lewy body disease."
  },
  "q3_human_cns_tissue": {
    "answer": "No",
    "evidence": "Organism part: olfactory mucosa; Samples: neurosphere-derived cell lines",
    "justification": "Samples are derived from olfactory mucosa and grown as in vitro neurospheres, not CNS tissue."
  },
  "q4_non_clinical": {
    "answer": "Yes",
    "evidence": "Title: Transcription profiling of neurosphere-derived cell lines from patients; Description: patient-derived cellular models",
    "justification": "The study uses patient-derived in vitro neurosphere cell lines rather than direct clinical tissue samples."
  },
  "q5_case_control_design": {
    "answer": "Yes",
    "evidence": "Experimental Factors: DISEASESTATE: normal, Parkinson's disease",
    "justification": "The design includes normal controls and Parkinson's disease cases."
  },
  "q6_irrelevant_brain_region": {
    "answer": "Yes",
    "evidence": "Organism part: olfactory mucosa",
    "justification": "Olfactory mucosa is not a CNS region significantly affected by Lewy body neurodegeneration."
  },
  "q7_familial_disease": {
    "answer": "No",
    "evidence": "Clinical/familial: Not found",
    "justification": "No indication that cases are familial; disease state appears sporadic."
  },
  "q8_incompatible_technology": {
    "answer": "No",
    "evidence": "Study type: transcription profiling by array",
    "justification": "The technology is microarray-based, which is compatible."
  },
  "q9_inclusion_justification": {
    "justification": "Although the dataset is human microarray data on Parkinson's disease with a case/control design, it uses patient-derived in vitro neurosphere cell lines from olfactory mucosa (non-CNS tissue) and not primary brain samples, so it fails criteria for relevant CNS tissue and involves non-clinical cell models."
  },
  "q10_include_dataset": {
    "answer": "No"
  }
}
